		dec, err := Resolve(req, in)
		if err != nil {
			t.Fatalf("Resolve: %v", err)
		}
		// Both same cost class. Healthy claude (+10) should beat burning codex (-20).
		if dec.Harness != "claude" {
			t.Errorf("quota trend: got %q, want claude (healthy)", dec.Harness)
		}
	})
}

