// cmdRouteStatus reports the routing engine's eligible-candidate trace for a
// requested intent (per ADR-005 §5). It calls service.ResolveRoute rather than
// enumerating route tables; score components and filter reasons come from the
// engine itself, not a parallel CLI implementation.
func cmdRouteStatus(workDir string, args []string) int {
	fs := flag.NewFlagSet("route-status", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	profile := fs.String("profile", "", "Routing profile (cheap|standard|smart)")
	model := fs.String("model", "", "Pin a specific model")
	modelRef := fs.String("model-ref", "", "Model catalog reference")
	provider := fs.String("provider", "", "Pin a specific provider")
	harness := fs.String("harness", "", "Pin a specific harness")
	minPower := fs.Int("min-power", 0, "Minimum catalog model power for automatic routing")
	maxPower := fs.Int("max-power", 0, "Maximum catalog model power for automatic routing")
	jsonOut := fs.Bool("json", false, "Output JSON")
	overrides := fs.Bool("overrides", false, "Print override_class_breakdown over a time window (ADR-006). "+
		"Operator-driven feedback loop; automatic learning is a future ADR. "+
		"Buckets with high override count and high outcome success rate suggest auto-routing is "+
		"picking suboptimally for that prompt class. Buckets with high override count and low "+
		"outcome success rate suggest users are pinning out of habit; consider UI nudges.")
	since := fs.String("since", "", "Time window for --overrides mode (Go duration, e.g. 24h, 168h). Default 7d (168h).")
	axis := fs.String("axis", "", "With --overrides, filter breakdown rows to overrides on this axis (harness|provider|model).")
	if err := fs.Parse(args); err != nil {
		return 2
	}

	if *overrides {
		return cmdRouteStatusOverrides(workDir, *since, *axis, *jsonOut)
	}
	if err := rootfizeau.ValidatePowerBounds(*minPower, *maxPower); err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 2
	}

	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	svc, err := rootfizeau.New(rootfizeau.ServiceOptions{
		ServiceConfig: agentConfig.NewServiceConfig(cfg, workDir),
		SessionLogDir: sessionLogDir(workDir, cfg),
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	decision, resolveErr := svc.ResolveRoute(ctx, rootfizeau.RouteRequest{
		Profile:  *profile,
		Model:    *model,
		ModelRef: *modelRef,
		Provider: *provider,
		Harness:  *harness,
		MinPower: *minPower,
		MaxPower: *maxPower,
	})

	out := routeStatusOutput{
		Profile:  *profile,
		Model:    *model,
		ModelRef: *modelRef,
		Provider: *provider,
		Harness:  *harness,
		MinPower: *minPower,
		MaxPower: *maxPower,
		PowerPolicy: routeStatusPowerPolicy{
			Profile:  *profile,
			MinPower: *minPower,
			MaxPower: *maxPower,
		},
		Candidates: []routeStatusCandidate{},
	}
	if resolveErr != nil {
		out.Error = resolveErr.Error()
	}
	if decision != nil {
		out.SelectedEndpoint = decision.Endpoint
		out.Sticky = decision.Sticky
		out.Utilization = decision.Utilization
		out.PowerPolicy = routeStatusPowerPolicy{
			Profile:  decision.PowerPolicy.Profile,
			MinPower: decision.PowerPolicy.MinPower,
			MaxPower: decision.PowerPolicy.MaxPower,
		}
		winnerSet := decision.Harness != "" || decision.Provider != "" || decision.Model != ""
		for _, c := range decision.Candidates {
			entry := routeStatusCandidate{
				Harness:       c.Harness,
				Provider:      c.Provider,
				Endpoint:      c.Endpoint,
				Model:         c.Model,
				Score:         c.Score,
				ContextLength: c.ContextLength,
				ContextSource: c.ContextSource,
				Eligible:      c.Eligible,
				FilterReason:  c.FilterReason,
				Reason:        c.Reason,
				CostSource:    c.CostSource,
				Utilization:   c.Utilization,
				Components: routeStatusComponents{
					Power:            c.Components.Power,
					Cost:             c.Components.Cost,
					CostClass:        c.Components.CostClass,
					LatencyMS:        c.Components.LatencyMS,
					SpeedTPS:         c.Components.SpeedTPS,
					SuccessRate:      c.Components.SuccessRate,
					QuotaOK:          c.Components.QuotaOK,
					QuotaPercentUsed: c.Components.QuotaPercentUsed,
					QuotaTrend:       c.Components.QuotaTrend,
					Capability:       c.Components.Capability,
					ContextHeadroom:  c.Components.ContextHeadroom,
				},
			}
			if winnerSet && out.Winner == nil &&
				c.Harness == decision.Harness &&
				c.Provider == decision.Provider &&
				c.Model == decision.Model {
				entry.Winner = true
				w := entry
				out.Winner = &w
			}
			out.Candidates = append(out.Candidates, entry)
		}
	}

	if *jsonOut {
		data, _ := json.MarshalIndent(out, "", "  ")
		fmt.Println(string(data))
		if resolveErr != nil && (decision == nil || decision.Harness == "") {
			return 1
		}
		return 0
	}

	if out.Profile != "" {
		fmt.Printf("Profile: %s\n", out.Profile)
	}
	if out.PowerPolicy.Profile != "" || out.PowerPolicy.MinPower > 0 || out.PowerPolicy.MaxPower > 0 {
		fmt.Printf("Power policy: profile=%s", labelOrUnknown(out.PowerPolicy.Profile))
		if out.PowerPolicy.MinPower > 0 {
			fmt.Printf(" min=%d", out.PowerPolicy.MinPower)
		}
		if out.PowerPolicy.MaxPower > 0 {
			fmt.Printf(" max=%d", out.PowerPolicy.MaxPower)
		}
		fmt.Println()
	}
	if out.Model != "" {
		fmt.Printf("Model: %s\n", out.Model)
	}
	if out.ModelRef != "" {
		fmt.Printf("Model Ref: %s\n", out.ModelRef)
	}
	if out.MinPower > 0 {
		fmt.Printf("Min Power: %d\n", out.MinPower)
	}
	if out.MaxPower > 0 {
		fmt.Printf("Max Power: %d\n", out.MaxPower)
	}
	if out.Winner != nil {
		fmt.Printf("Winner: %s/%s/%s endpoint=%s score=%.2f\n", out.Winner.Harness, out.Winner.Provider, out.Winner.Model, out.Winner.Endpoint, out.Winner.Score)
	}
	if out.SelectedEndpoint != "" {
		fmt.Printf("Selected endpoint: %s\n", out.SelectedEndpoint)
	}

package agentcli

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/DocumentDrivenDX/fizeau"
)

func TestRouteStatusOutputIncludesPowerPolicy(t *testing.T) {
	out := routeStatusOutput{
		Profile: "standard",
		PowerPolicy: routeStatusPowerPolicy{
			Profile: "standard",
		},
	}
	data, err := json.Marshal(out)
	if err != nil {
		t.Fatalf("Marshal: %v", err)
	}
	if !strings.Contains(string(data), `"power_policy"`) {
		t.Fatalf("JSON missing power_policy field: %s", data)
	}
	if !strings.Contains(string(data), `"profile":"standard"`) {
		t.Fatalf("JSON missing profile evidence: %s", data)
	}
}

// TestRouteStatusOverridesSinceFilter verifies that --since trims the
// breakdown window. Three session logs are written: one 1h ago (inside
// every window), one 48h ago (inside 7d but outside 24h), one 30d ago
// (outside both).
func TestRouteStatusOverridesSinceFilter(t *testing.T) {
	workDir := t.TempDir()
	logDir := filepath.Join(workDir, ".fizeau", "sessions")
	if err := os.MkdirAll(logDir, 0o755); err != nil {
		t.Fatalf("mkdir: %v", err)
	}
	now := time.Now().UTC()
	writeOverrideSessionLog(t, logDir, "s-1h", now.Add(-time.Hour), "harness", false, "success")
	writeOverrideSessionLog(t, logDir, "s-48h", now.Add(-48*time.Hour), "harness", false, "success")
	writeOverrideSessionLog(t, logDir, "s-30d", now.Add(-30*24*time.Hour), "harness", false, "success")

	// 24h window: only s-1h is inside.
	out := runRouteStatusOverridesJSON(t, workDir, "24h", "", now)
	if out.TotalOverrides != 1 {
		t.Fatalf("--since=24h: TotalOverrides = %d, want 1", out.TotalOverrides)
	}
	totalCount := 0
	for _, b := range out.OverrideClassBreakdown {
		totalCount += b.Count
	}
	if totalCount != 1 {
		t.Errorf("--since=24h: breakdown count sum = %d, want 1", totalCount)
	}

	// Default 7d window (--since="" → 168h): s-1h + s-48h.
	out = runRouteStatusOverridesJSON(t, workDir, "", "", now)
	if out.TotalOverrides != 2 {
		t.Fatalf("default 7d: TotalOverrides = %d, want 2", out.TotalOverrides)
	}

	// 168h is the explicit equivalent of the default and must produce the
	// same result as the default window.
	out2 := runRouteStatusOverridesJSON(t, workDir, "168h", "", now)
	if out2.TotalOverrides != out.TotalOverrides {
		t.Errorf("168h vs default: TotalOverrides %d vs %d should match",
			out2.TotalOverrides, out.TotalOverrides)
	}

	// 24h header text mentions the chosen window.
	textOut, _ := runRouteStatusOverridesText(t, workDir, "24h", "", now)
	if !strings.Contains(textOut, "Window: ") {
