				if entry.CostInputPerM == 0 {
					entry.CostInputPerM = target.CostInputPerM
				}
				if entry.CostOutputPerM == 0 {
					entry.CostOutputPerM = target.CostOutputPerM
				}
				if entry.CostCacheReadPerM == 0 {
